diff --git a/mail/themes/linux/mail/contextMenu.css b/mail/themes/linux/mail/contextMenu.css
index ddd7f54b8d5..2bc6e26441d 100644
--- a/mail/themes/linux/mail/contextMenu.css
+++ b/mail/themes/linux/mail/contextMenu.css
@@ -4,6 +4,15 @@

 @import url("chrome://messenger/skin/shared/contextMenu.css");

-menupopup > menuitem:is([type="checkbox"],[type="radio"]) .menu-icon {
-  appearance: none;
+menupopup {
+  & > menuitem:is([type="checkbox"],[type="radio"]) .menu-icon {
+    appearance: none;
+  }
+
+  &.webextension-menupopup > menu:not([icon], .menu-iconic),
+  &.webextension-menupopup > menuitem:not([checked="true"], [icon], .menuitem-iconic),
+  menubar > menu
+    &:not([needsgutter]) > :is(menu:not(.menu-iconic),menuitem:not(.menuitem-iconic)) {
+    padding-inline-start: calc(24px + 0.5em);
+  }
 }
